<?php
require __DIR__.'/../app/bootstrap.php'; require_login();
$assetNo=preg_replace('/[^0-9]/','',(string)($_GET['asset_no']??''));if(!preg_match('/^\d{7}$/',$assetNo))redirect('assets.php');$q=db()->prepare('SELECT source_file FROM assets WHERE asset_no=?');$q->execute([$assetNo]);$stored=(string)($q->fetchColumn()??'');if($stored==='')exit('فایل منبعی ثبت نشده است.');$name=basename($stored);if(!preg_match('/^[a-f0-9]{32}\.csv$/',$name))exit('فایل منبع قابل دریافت نیست.');$path=upload_storage_dir().DIRECTORY_SEPARATOR.$name;if(!is_file($path))exit('فایل منبع روی سرور موجود نیست.');audit('source_download','asset',$assetNo);header('Content-Type:text/csv; charset=UTF-8');header('Content-Disposition:attachment; filename="hardware-'.$assetNo.'.csv"');header('Content-Length:'.filesize($path));readfile($path);exit;
